begin;
create function public.cms_public_course(p_slug text) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',c.id,'title',c.title,'description',p.metadata->>'description') from public.courses c left join private.content_publications p on p.entity_kind='course' and p.entity_id=c.id where c.slug=p_slug and private.content_visible('course',c.id) and public.billing_resource_access('courses',c.id)$$;
create function public.cms_lesson_slug(p_course text,p_slug text) returns uuid language sql stable security definer set search_path='' as $$select l.id from public.lessons l join public.courses c on c.id=l.course_id where c.slug=p_course and l.slug=p_slug and private.content_visible('lesson',l.id) and public.billing_resource_access('lessons',l.id)$$;
create function public.cms_kanji(p_level text default 'n5') returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('id',k.id,'character',k.character,'onyomi',k.onyomi,'kunyomi',k.kunyomi,'meaning',k.meaning,'example_words',k.example_words,'lesson_id',case when private.content_visible('lesson',k.lesson_id) and public.billing_resource_access('lessons',k.lesson_id) then k.lesson_id else null end)),'[]') from public.kanji_entries k join public.courses c on c.id=k.course_id where c.slug=p_level and k.published and private.content_visible('course',c.id) and public.billing_resource_access('kanji_entries',k.id)$$;
create function public.cms_content_sitemap() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('path',case p.entity_kind when 'lesson' then 'courses/'||c.slug||'/lessons/'||l.slug else case when c.slug in ('n5','n4','n3','n2','n1') then 'courses/'||c.slug else 'programs/'||g.slug||'/'||c.slug end end,'updated_at',p.published_at,'indexable',coalesce((p.seo->>'index')::boolean,false),'locales',array['en','ja'])),'[]') from private.content_publications p left join public.lessons l on p.entity_kind='lesson' and l.id=p.entity_id join public.courses c on c.id=case p.entity_kind when 'lesson' then l.course_id else p.entity_id end left join public.learning_programs g on g.id=c.program_id where p.entity_kind in ('course','lesson') and private.content_visible(p.entity_kind,p.entity_id) and public.billing_resource_access('courses',c.id) and (p.entity_kind<>'lesson' or public.billing_resource_access('lessons',l.id)) and (p.entity_kind='lesson' or c.slug in ('n5','n4','n3','n2','n1') or g.published)$$;
alter function public.cms_content_sitemap() rename to cms_content_sitemap_core;
alter function public.cms_content_sitemap_core() set schema private;
revoke all on function private.cms_content_sitemap_core() from public,anon,authenticated;
create function public.cms_content_sitemap() returns jsonb language sql stable security definer set search_path='' as $$select private.cms_content_sitemap_core()||coalesce((select jsonb_agg(jsonb_build_object('path','japan-guide/'||a.slug,'updated_at',p.published_at,'indexable',coalesce((p.seo->>'index')::boolean,false),'locales',array['en']||coalesce((select array_agg(locale) from public.guide_translations where article_id=a.id and review_status='approved' and article_version=a.version),'{}'::text[]))) from private.content_publications p join public.guide_articles a on a.id=p.entity_id where p.entity_kind='guide_article' and private.guide_visible(a.id)),'[]')$$;
alter table private.media_assets add column deleted_at timestamptz;
create function public.cms_media_prepare_delete(p_actor uuid,p_id uuid) returns text language plpgsql security definer set search_path='' as $$declare path text;begin
 if not exists(select 1 from auth.users u where u.id=p_actor and to_jsonb(u)->>'email_confirmed_at' is not null) or not (exists(select 1 from private.admin_users where user_id=p_actor) or exists(select 1 from private.admin_role_assignments where user_id=p_actor and role in ('super_admin','content_admin'))) then raise exception 'Verified publisher required';end if;
 select object_path into strict path from private.media_assets where id=p_id for update;
 if exists(select 1 from private.media_links where asset_id=p_id) or exists(select 1 from private.content_workspaces where document::text like '%'||p_id::text||'%') then raise exception 'Referenced media cannot be deleted';end if;
 update private.media_assets set status='archived',updated_at=clock_timestamp() where id=p_id;
 insert into private.admin_audit_logs(actor_id,action,entity_kind,entity_id) values(p_actor,'media_delete_requested','media',p_id);return path;
end$$;
create function public.cms_media_delete_result(p_actor uuid,p_id uuid,p_success boolean) returns void language plpgsql security definer set search_path='' as $$begin
 if p_success then update private.media_assets set deleted_at=clock_timestamp() where id=p_id and status='archived';end if;
 insert into private.admin_audit_logs(actor_id,action,entity_kind,entity_id) values(p_actor,case when p_success then 'media_deleted' else 'media_delete_failed' end,'media',p_id);
end$$;
revoke all on function public.cms_public_course(text),public.cms_lesson_slug(text,text),public.cms_kanji(text),public.cms_content_sitemap(),public.cms_media_prepare_delete(uuid,uuid),public.cms_media_delete_result(uuid,uuid,boolean) from public;
grant execute on function public.cms_public_course(text),public.cms_lesson_slug(text,text),public.cms_kanji(text),public.cms_content_sitemap() to anon,authenticated;
do $$begin if exists(select 1 from pg_roles where rolname='service_role') then grant execute on function public.cms_media_prepare_delete(uuid,uuid),public.cms_media_delete_result(uuid,uuid,boolean) to service_role;end if;end$$;
commit;
